                        new
                        {
                            Id = 22,
                            Author = "رامي احمد مصطفى",
                            CategoryId = 6,
                            CreatedAt = new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc),
                            Description = "زائرة مجهولة بفستان زفاف.\nبلاغ مرتبك عن جريمة قتل.\nواختفاء يربك كل ما يبدو واضحًا.\n\nمن شذرات متفرقة ومعطيات ناقصة، أجد نفسي مدفوعةً إلى خوض تجربتي الأولى في الكتابة.\nلا بوصفها بحثًا عن حل.\nبل كتجربة يحركها الفضول والشك.\n\nالنص لا يعد بإجابات.\nولا يمنح يقينًا.\nإنه اقتراب بطيء من لغز.\nواعتراف بأن بعض القصص لا تُحكى… بل تُعاش.\n“و.م”",
                            ImageUrl = "/images/products/9789778203356.webp",
                            Isbn = "9789778203356",
                            Name = "بعض ما ورد بشأنها",
                            Pages = 248,
                            Price = 230m,
