                        new
                        {
                            Id = 45,
                            Author = "عبد الله مكسور",
                            CategoryId = 1,
                            CreatedAt = new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc),
                            Description = "ما جرى في هذه الحكاية يقع كل يوم، عندما أقول كل يوم فإني أعني ذلك، من الساعة الرابعة فجرًا حتى السادسة مساءً، في أوقات لا يلتفت فيها العالم إلى شيءٍ سوى نفسه.\nيحدث هذا خارج نشرات الأخبار، وخارج اللغة الكبيرة. في ساعات الانتظار التي لا تُحسب من العمر لكنها تستهلكه. لهذا فما حدث في الحكاية ليست لحظة استثنائية، بل واحدة من لحظات كثيرة تتشابه إلى حدِّ التطابُق والقسوة، فيما تختلف فقط بأسماء العابرين وأيام الأسبوع.\nكل ما يرد في الحكاية مقصود ومدروس كجزء من لعبة الشاباك، إنها رواية على شكل وقوف طويل أمام بابٍ مفتوحٍ نصف فتحة، تساؤل صامت عمَّا إذا كان العبور بحثًا عن معنى، أم إضافة اسمٍ آخر إلى سجل الامتيازات؟\nحكاية تبدأ بتباطؤ مقصود؛ لأن بعض الحكايات لا تحتاج افتتاحية صاخبة، وإنما تحتاج شجاعة الاعتراف الأول بأن الدخول ليس بسيطًا، وأن الكتابة نفسها عبء، وأن حمل هذا العبء هو الشرط الوحيد للمضي قُدمًا نحو عبورٍ مؤجَّل.\nعبد الله مكسور، روائي وصحفي عربي من مواليد سوريا، صدرت له سبعة أعمال روائية وكتاب «هندسة المعنى» في الصحافة والإعلام. يعمل في الصحافة منذ عام 2007م، كما عمل في المسرح البلجيكي، ولديه خبرة طويلة تمتد لأكثر من عقدين في العمل التلفزيوني والتدريب على تقنيات الكتابة الإبداعية والفنون الصحفية، تُدرَّس أعماله ضمن مساقات الكتابة الحديثة في العديد من الجامعات.",
