                        new
                        {
                            Id = 62,
                            Author = "سهير عبدالحميد",
                            CategoryId = 7,
                            CreatedAt = new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc),
                            Description = "«فلاح خرسيس».. كانت هذه الجملة الشهيرة تتردَّد على لسان الباشا صاحب العِزبة، وهو يحمل الكُرباج بيده ويهوي به على ظهور الفلاحين المحنية بفعل القهر! صورة رسَّختها الدراما المُسيَّسة في أذهاننا، وهي تصنع في عقولنا ذلك الارتباط الشَّرْطي المعيب بين البكوات والباشوات من جانب، وبين الإقطاع والاستغلال الاقتصادي والسياسي من جانب آخر. صحيح أن ألقاب البكوات والباشوات كانت كالسلعة تُباع وتُشتَرى، لكن هناك رجال حصلوا عليها عن جدارة، ودون سعي منهم أو طلب. رجال قدَّموا لهذا البلد ما ظل كشجرةٍ وارفةِ الظلال، أصلها ثابت وفرعها في السماء.\nإن هذا الكتاب يتناول تاريخ ما أهمله التاريخ: سِيَر رجال كانت إنجازاتهم أعلى من الألقاب، وفي ثنايا حكاياتهم وجبة دسمة من تاريخ مصر جغرافيًّا وسياسيًّا واقتصاديًّا واجتماعيًّا، وجرعة مكثفة من تاريخ الحجر والبشر، الزمان والمكان، وتصحيح لمفاهيم مغلوطة رسَّختها حركة 23 يوليو التي شابها عوار سياسي وإنساني واقتصادي وقانوني. وكان العوار الأكبر - في تقديري - هو محاولتها تزييف الوعي الجمعي عَبْرَ مَن يحلو لي تسميتهم «ترزية التاريخ».\nسهير عبد الحميد، كاتبة صحفية، مدير تحرير «الأهرام»، وباحثة في التاريخ. صدر لها: قصور مصر، إسكندرية من تاني، اغتيال قوت القلوب الدمرداشية، على عتبة المقام، سلسال الباشا، ناحوم أفندي، يهود الظاهر.",
                            ImageUrl = "/images/products/9789777955782.webp",
                            Isbn = "9789777955782",
                            Name = "بكوات وباشوات",
                            Price = 330m,
                            PublishDate = new DateTime(2026, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc),
                            Stock = 10,
                            TopRated = false
                        },
                        new
                        {
                            Id = 63,
                            Author = "أحمد الشهاوي",
                            CategoryId = 8,
                            CreatedAt = new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc),
                            Description = "رحلةٌ عمليةٌ ومُلهِمةٌ في أسرارِ الإبداعِ كما عاشها ودوَّنها سبعة عشر كاتبًا وكاتبةً من مشاهير الأدب العالمي.\nلا تُقَدَّم الكتابةُ هنا بوصفها موهبةً غامضةً حكرًا على قلةٍ مُختارةٍ، بل كمسارٍ يمكنُ تعلُّمُهُ وصقلُه وتطويرُهُ عبر استراتيجياتٍ واضحةٍ ونصائح مجرَّبة. تجمعُ المترجمة والشَّاعرة والأكاديمية سارة حامد حوَّاس خلاصاتِ تجارب هؤلاء الكُتَّاب، وتعيدُ تقديمَها إلى القارئ ، لتضعَ بين يديه مفاتيح للكتابةِ المؤثِّرةِ ..كيف تبدأ؟ كيف تستمرُ؟ كيف تتغلبُ على الخوفِ والتردُّد وحبسة الكتابة؟ وكيف تُحوِّلُ الأفكار المُبعثرة إلى نصٍّ ينبضُ بالمعنى؟\nما يجعل هذا الكتاب مختلفًا هو أنه لا يكتفي بسردِ تجارب الآخرين، بل يُحفِّزُك على النظرِ إلى نفسِكَ ككاتبٍ مُحتملٍ، ويطرحُ أسئلةّ تجعلك تعيدُ التفكيرَ في علاقتكَ بالكتابةِ، ولماذا تكتبُ، ولمَن.\nإنه كتابٌ يشبهُ ورشةَ كتابةٍ مفتُوحةً، ومرشدًا صامتًا يرافقُكَ خُطوةً بخطوةٍ.\nد. سارة حامد حوَّاس، مدرس بقسم اللغة الإنجليزية، بآداب المنصورة، مترجمة وشاعرة. صدر لها في الترجمة والشِّعْر عدة كتب، منها: \"ثُقب المفتاح لا يَرَى.. عشرون شاعرة أمريكية حائزات على جائزتيْ نوبل وبوليتزر\"، الذي وصل إلى القائمة القصيرة لجائزة جابر عصفور للترجمة، و\"ولاؤهم للروح.. عشرون شاعرًا أمريكيًّا حائزًا على جائزة بوليتزر\"، و\"في قلبي قارة.. عشرون شاعرة وشاعرًا أفرو‑أمريكيًّا\"، وترجمة كتاب \"قبلة رُوحي\".. مختارات من شعر أحمد الشهاوي صدرت في كلكتا بالهند، وديوانها الشعري \"جبل على كتفي\".\nتحرير وتقديم :- احمد الشهاوى",
