                        new
                        {
                            Id = 65,
                            Author = "ميخائيل عماد",
                            CategoryId = 1,
                            CreatedAt = new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc),
                            Description = "في حفل توقيع روايته الجديدة بفندق الماريوت٬ يفاجئ الكاتب الشهير (يوسف سليمان التركي) بزائر خاص من الماضي٬ كيان شيطاني يتخذ شكل (فرانز كافكا). وقبل أن يهرب منه يوسف يحتجزه كافكا في مصعد الفندق ليخبره أن الليلة ليست ليلة عادية٬ وانما ليلة الحساب ودفع الثمن للعقد الذي أبرماه معًا منذ 15 عامًا٬ وأن يوسف سيمضي ليلة خاصة سوداء٬ مُطارد من قِبل كل ذنوبه، لأن هناك عدوًا خفيًّا له حصل على امتياز كتابة ليلة كاملة من حياته، وأن كل ما سيكتبه سيحدث.\nتدور الرواية في ثلاث ليال٬ الليلة الرئيسية في حاضر ٬2025  وليلتان من العام 2010. نرى خلالها كيف بدأت العلاقة بين يوسف وذلك الشيطان، وكيف تخلى الكاتب المغمور عن مبادئه أمام الغواية، وكيف سقط في بئر سحيقة مطاردًا أحلامه، وكيف سينعكس ذلك على ليلة خاصة جدًّا من حاضره، سيهرب فيها من ماضيه وذنوبه، وسيطارد كاتبًا مهووسًا يريد تدميره، في ليلة مليئة بالندم والدماء، والألغاز، والبحث عن الخلاص، والنبش في الماضي.\nميخائيل عماد، صيدلاني وروائي مصري من مواليد 1995، صدرت له أربع روايات حتى الآن٬ من ضمنها (أثر اليعسوب) و(الخريف في بالم تاون) واستطاع لفت الأنظار عن طريق صوت أدبي خاص وأفكار غير معتادة. كما شارك في كتابة عدة مسلسلات وأفلام وبرامج مثل (الدحيح) و(في الحضارة).",
