                        new
                        {
                            Id = 71,
                            Author = "ميرنا الهلباوي",
                            CategoryId = 1,
                            CreatedAt = new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc),
                            Description = "هل كان سر نجاح كوكو شانيل هو عمر أفندي؟\nثم ما علاقة مزارع الياسمين في دلتا مصر بسجون هتلر النازية في ألمانيا؟\nولماذا استقل الدكتور سيجموند فرويد قطار الإسكندرية- القاهرة متجهًا إلى جاردن سيتي في مصر؟\nوما العامل المشترك بين الفنان الإسباني سلفادور دالي وأمينة الفلاحة المصرية البسيطة؟\nوهل يمكن تخيل ارتباطٍ وثيقٍ بين الفرنسي چاستون ماسبيرو رئيس مصلحة الآثار المصرية والمقاومة الفلسطينية؟\nفيليب باخ بطل هذه الرواية المثيرة هو الوحيد الذي لديه إجابات عن هذه الأسئلة الغريبة.\nرواية مستوحاة من أحداث حقيقية لرجل عادي ذي أثر مذهل، تحتار في تصنيفه هل هو بطل أم أناني لدرجة تثير الغيظ؟\nكان فيليب باخ يصر على معاندة أقداره وتجاهلها لينتهي به الأمر في رحلة حياة جنونية وخطيرة عكس كل ما يتمناه من الهدوء والحب والسعادة.\nميرنا الهلباوي: كاتبة وإعلامية مصرية. عملت في الصحافة، وترشحت للقائمة النهائية لجائزة الصحافة العربية. عملت مذيعة في راديو NRJ ومراسلة استقصائية مع شبكة BBC للتحقيقات الوثائقية. لديها ثلاثة إصدارات من الأكثر مبيعًا: \"مر مثل القهوة حلو مثل الشوكولا\" و\"كونداليني\" و\"تنذكر ما تنعاد\". وهي مؤسسة حملة Connecting Gaza ومنظمة Connecting Humanity غير الهادفة للربح.",
                            ImageUrl = "/images/products/9789777955577.webp",
                            Isbn = "9789777955577",
