                        new
                        {
                            Id = 73,
                            Author = "عمار على حسن",
                            CategoryId = 1,
                            CreatedAt = new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc),
                            Description = "يضم هذا الكتاب سبعين حكاية خرافية، يتداولها الناس في قرى مصر ومدنها، عمن يستحضرون الجان، أو ما يأتيه السحرة والمشعوذون والعرافون من قارئي الكف والتاروت والفنجان والمَندل وضاربي الودَع والمهتمين بحسابات النجوم والفلك، والساعين خلف الكنوز المطمورة، والمبالغين في تصوير كرامات الأولياء والقديسين، والمعتقدين في التمائم والحروز والطلاسم، ومَن يشغلهم الخوف من الحسد والعفاريت، وتجذبهم حكايات عمَّا بعد الموت، ويصدقون النبوءات القديمة، وأولئك الذين يؤمنون بالفيوضات الروحية التي تجلب الطاقة الإيجابية، ومَن يتمسكون بأرقام وأشياء جالبة للحظ.\nلقد سمعت من أهل قريتي هذه الحكايات العجيبة صغيرًا، وتعاملت معها كمادة خام لعمل أدبي، قاصدًا ألا أتركها في سيلانها وجريانها على الألسنة هائمة عائمة، إنما راسية بين سطور مكتوبة، هي في خاتمة المطاف روايتي لهذه الحكايات العجيبة المدهشة المملوءة بالشغف والرعب والإيهام والإلهام والأمل.\nسبعون حكاية عن عوالم خفية، لعل القارئ يكتشف بها ومعها ثراء مخيلة أهلنا الذين سردوا هذه الحكايات عبر آلاف السنين، ويكتشف في رحابها قدرة جيلنا على الاستفادة منها، وتقديمها سِفرًا من أسفار عجائبيتنا وغرائبيتنا الساحرة.\nعمار علي حسن، أديب ومفكر مصري، أصدر اثنين وستين كتابًا، نصفها أعمال أدبية هي روايات ومجموعات قصصية ودواوين شعرية ومسرحية وسيرة ذاتية ونصوص عابرة للأنواع، ونصفها الآخر كتب في الاجتماع السياسي، والنقد الأدبي والثقافي، والتصوف، والفكر. أُعدت حول رواياته وقصصه عشرون رسالة جامعية داخل مصر وخارجها، وصدرت عنها كتب ودراسات نقدية، وتُرجمت بعض أعماله العلمية والأدبية إلى عدة لغات، ونال عنها جوائز كبرى.",
