                        new
                        {
                            Id = 74,
                            Author = "احسان عبد القدوس",
                            CategoryId = 1,
                            CreatedAt = new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc),
                            Description = "\"وعاد زوجي من إحدى سهراته «الرجالي» بعد منتصف الليل.. وأيقظني بقبلاته.. وأخذ يروي لي تفاصيل سهراته مع أصدقائه.. ونمنا.\nوفي الصباح، وعندما كنت أضع يدي في جيوبه لأنقل حاجياته من بدلة إلى بدلة تعلقت عيني بمنديله..\nلقد كان في المنديل بقعة كبيرة من آثار أحمر شفاه، تلمع أمام عيني كأنها جذوة من نار..وتصاعدت الدماء إلى رأسي.. أحسست أن الدنيا تدور بي.. وأن كتلًا من الظلام تتجمع أمام عيني حتى لم أعد أرى شيئًا..\".\nولد أول يناير 1919 بالقاهرة، تخرج في كلية الحقوق عام 1942.  بدأ حياته كاتبًا سياسيّا ورئيسًا لتحرير مجلة روزاليوسف التي أسستها والدته فاطمة اليوسف. فجّر قضية الأسلحة الفاسدة التي استخدمت في حرب فلسطين.  تقلد عددًا من المناصب الصحفية كان آخرها رئيسًا لتحرير ولمجلس إدارة مؤسسة الأهرام، وبعدها تفرغ للكتابة حتى وفاته 11 يناير 1990.  أنتج المئات من الروايات والمجموعات القصصية التي تحوّل معظمها إلى أعمال سينمائية وإذاعية وتليفزيونية. حصل على العديد من أرفع الأوسمة والجوائز وشهادات التقدير المحلية والعالمية.",
