                        new
                        {
                            Id = 78,
                            Author = "أحمد حمدان",
                            CategoryId = 8,
                            CreatedAt = new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc),
                            Description = "هذا الكتاب رحلة لم تبدأ لتصل، بل لتفتح دروبًا جديدة في بحرٍ لا ساحل له. رحلة تجول بين مدارات القانون، تغوص في أعماقه، وتستضيء بمصابيحه، لتقتنص قبسًا من نور يروي عطش العقول، ويوقظ الأرواح التائقة للمعرفة. إنّه دعوة لاكتشاف مذاقات فكرية لم يجرّبها كثيرون، ولقاء مع حقائق لم يُظن يومًا بوجودها.\nوهذا الكتاب ما هو إلا لبنة في مشروع أكبر، وسطر في سلسلة أوسع تنشد تجديد الصناعة القانونية، وبناء عقلٍ قانونيّ متوثّب، جذرُه في أصولنا الشرعية ومصالحنا المرعية، وفرعُه ممتدّ إلى فضاء الفكر الإنساني الرحب. غايته أن يزرع بذور الوعي، ويُقيم جسور الإلهام، ويُرشد الحائر، ويُلهم العاثر.\nومن رحم هذه الرؤية وُلدت مؤسسة رشد المعارف \"رشد\"، لتكون أيقونة تغيير وإلهام في فضاء القانون والمعرفة. لم تُؤسَّس لتُضاف إلى أعداد المؤسسات القائمة، بل لتكون بصمة متفرّدة، ومَعلَمًا يُهتدى به، ومشروعًا يستلهم من تراثنا الأصيل، وينفتح على تجارب الإنسانية العظمى.\nإن الإنتاج المعرفي الذي تبشّر به \"رشد\" ليس غاية مكتفية بذاتها، بل وسيلة لإعادة صياغة العقل القانوني، وبنائه على الفهم الراسخ، والوعي النافذ، والإبداع الخلّاق. هي مشاريع تحمل وعدًا لجيلٍ جديد من القانونيين؛ جيل يعبر حدود المألوف، ليؤسس لآفاقٍ يستطيع أن يكون فيها أثبتَ قَدمًا، وأبعد رؤيةً، وأعمق فهمًا.\nد.فارس بن محمد القرني",
                            ImageUrl = "/images/products/9789777955591.webp",
