                        new
                        {
                            Id = 88,
                            Author = "إبراهيم عيسى",
                            CategoryId = 1,
                            CreatedAt = new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc),
                            Description = "في حقبة التسعينيات، حيث كانت الصحافة تكاد تكون  السلطة الرابعة، و الصراع فيها كاشف عن تشابك دوائر السياسة والسلطة والنفوذ وحيث خيوط شبكتها تصطاد الجميع، يأتي هذا الصحفي الشاب من عالم الريف والجامعة والبراءة غريبًا في وسط ينشب مخالبه في قلبه وشاهدًا على معارك لا ينتصر فيها إلا الألم، يكتشف الحقيقة عن تجلي العذراء في أحد أحياء القاهرة. تلك  الحقيقة التي كان يتمنى ألا يعرفها أبدًا.\n\"مريم التجلي الأخير\" رواية مثيرة للكاتب الكبير إبراهيم عيسى، تدور بين مكاتب الصحافة الصاخبة ودهاليز السياسة الغامضة، حيث لا مكان يصلح للبراءة ولا مدينة ترحب بالأبرياء، حيث يمتزج الواقع بالزيف، والإيمان بالشك، والحقيقة بالأكاذيب.\nرواية عن زمن كان كل شيء فيه قابلًا للانفجار.\nإبراهيم عيسى صحفي وروائي مصري، مواليد نوفمبر 1965. عمل صحفيًّا بمؤسسة روز اليوسف و في عام 1995 تولى رئاسة تحرير جريدة الدستور قبل مصادرتها عام 1998 ثم أعاد تأسيسها ورئاسة تحريرها عام 2004 وحتى 2010، كما تولى رئاسة تحرير جريدة التحرير في عام2011 ثم أسس ورأس تحرير جريدة المقال في 2015. حصل على جائزة جبران تويني التي يمنحها الاتحاد العالمي للصحف 2008، كما حصل على جائزة الصحافة الحرة من منظمة إنديكس العالمية 2010، وجائزة أحسن صحفي في العالم من نقابة الصحافة البريطانية عام2011. له مؤلفات روائية وسينمائية ودرامية عديدة. كسرت رواياته الحاجز التقليدي للرواية العربية فتعدى حدود الزمان و المكان، وكان من أوائل رواد الواقعية السحرية.",
                            ImageUrl = "/images/products/9789777955386.webp",
                            Isbn = "9789777955386",
