                        new
                        {
                            Id = 91,
                            Author = "شريف صالح",
                            CategoryId = 1,
                            CreatedAt = new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc),
                            Description = "\"مرة ثانية التقينا في مقهى الفيشاوي. شربنا الشاي الخفيف بالنعناع. سمحتُ لنفسي أن أحضن يدها الصغيرة بين يديّ. أغمضتْ عينيها. كان في أصابعها بعض العُقل البارزة وعروق مزرقة.\nقالت بخجل:\nـ \"يدي ليست جميلة\".\nـ \"بالعكس. فيها شيء عنيد وطموح\".\nكانت كذبتي الأولى. كيف يكون في اليد شيء عنيد وطموح؟!\".\n\"مجانين أم كلثوم\" لا توثق فقط سيرة أكبر مطربة عربية، وإنما تقدم رؤيةً سرديةً مبتكرة لأغانيها التي أصبحت جزءًا من الوجدان العربي، وتأريخًا ثقافيًا للقرن العشرين في مصر.\nكما يُحسب للرواية أنها لم تتوقف عند أضلاع الأغنية الثلاثة: الشاعر والملحن والمطربة، وإنما أبرزت الضلع الرابع وهو جمهور الست، أولئك الذين صنعوا أسطورتها. وبفضلهم لا تزال موسيقاها تصدح في البيوت والشوارع والمقاهي من المحيط إلى الخليج.\nوإلى الأبد، سيظل صوتها ونسًا للمحبين والناس الطيبين؛ ينتصرون به على الحروب العبثية وبؤس الأيام.\nشريف صالح، كاتب وصحفي مصري. دكتوراه في النقد الأدبي من أكاديمية الفنون. حصل على عديد من الجوائز، منها: \"ساويرس\" عن مجموعة \"مثلث العشق\"، و\"دبي الثقافية\" عن مجموعة \"بيضة على الشاطئ\"، و\"الشارقة\" للإصدار الأول عن مسرحية \"رقصة الديك\". له نحو عشرين كتابًا، منها: رواية \"حارس الفيسبوك\" و\"ابتسامة بوذا\" و\"نجيب محفوظ وتحولات الحكاية\".",
                            ImageUrl = "/images/products/9789777955270.webp",
