                        new
                        {
                            Id = 106,
                            Author = "إبراهيم عيسى",
                            CategoryId = 7,
                            CreatedAt = new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc),
                            Description = "يعود إبراهيم عيسى بعد أربع سنوات من صدور «مولانا» (القائمة القصيرة للجائزة العالمية للرواية العربية – البوكر 2013) ليتناول المسكوت عنه في تاريخنا الإسلامي. ففي سرد مبهر وأحداث مشوقة إلى أقصى درجة يربط ببراعة بين صراعات المسلمين الأوائل بعد وفاة الرسول وفتح مصر واغتيال عثمان بن عفان وعلي بن أبي طالب. إن إبراهيم عيسى يخلق لنا – ولأول مرة – صورة أقرب ما تكون للحقيقة عن هذه السنوات المهمة والتي غيرت وجه العالم للأبد.\nسيُذهل القارئ عندما يعرف أن جميع شخصيات هذه الرواية حقيقية، وأن كل أحداثها تستند على وقائع وردت في المراجع التاريخية المعتمدة. وهي الجزء الأول من سلسلة «القتلة الأوائل».",
                            ImageUrl = "/images/products/9789776467569.webp",
