                        new
                        {
                            Id = 107,
                            Author = "إبراهيم عيسى",
                            CategoryId = 7,
                            CreatedAt = new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc),
                            Description = "المؤلف من أكثر الكتاب مبيعًا\nالجزء الأول من السلسلة الروائية من أكثر الكتب مبيعًا\nرحلة الدم لم تنتهِ إذن.\nبل إن الدم أكثر وأغزر.\nلم تكن أبدًا فتنة، بل أعمق وأخطر.\nانسَ كل ما كنت تعرفه عن الفتنة الكبرى، فأنت تدنو من الحقيقة الآن في سردٍ أقرب إلى الواقع وأكثر تشويقًا مع هذه الرواية التي يستكمل بها إبراهيم عيسى مسيرة «القتلة الأوائل»، والتي بدأها في «رحلة الدم» (جائزة نجيب محفوظ في الرواية 2018)، ليتناول السنوات اللغز في تاريخنا الإسلامي.\nونؤكد للقارئ مرَّة أخرى أن جميع شخصيات هذه الرواية المبهرة حقيقية، وأن كل أحداثها تستند إلى وقائع وردت في المراجع التاريخية المعتمدة.",
                            ImageUrl = "/images/products/9789776467996.webp",
