                        new
                        {
                            Id = 108,
                            Author = "إبراهيم عيسى",
                            CategoryId = 7,
                            CreatedAt = new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc),
                            Description = "المؤلف من أكثر الكتاب مبيعًا\nالجزءان الأوليان من أكثر الكتب مبيعًا\n«سيوف الآخرة» هي الرواية التي تصل بك إلى المحطة الأخيرة، أو التي تظنها كذلك في «رحلة الدم». يكمل إبراهيم عيسى هنا دائرة «القتلة الأوائل» منذ اللحظة التي قتل فيها عثمان بن عفان حتى مقتل علي بن أبي طالب. العديد من الألغاز التي تكونت وتراكمت في كتب التاريخ تفكها هذه الرواية، تكشفها وتعريها من غموضها ومن كذبها وربما من تلفيقها. والكثير من الثقوب السوداء التي هوت فيها الحقيقة، وردمت فوقها أضاليل الركام تنفضها «سيوف الآخرة»، تنقب عنها وتعثر عليها، حيث تزيح الأوهام والأكاذيب والتخيلات والتوهمات والدعايات من عقل القارئ ليرى مفاجأة وصدمة ودهشة لقائه بالحقيقة كأنه يراها أو يعيشها، أو كأنه عاش أخيرًا كي يراها.\nلعل أهم ما ستضمنه لك قراءة «سيوف الآخرة»، مع التشويق والإثارة وسرعة نبضات القلب وارتفاع طفيف في ضغط الدم، أنك تستحق أن تعرف لماذا تسمع وترى الآن، وبعد مئات السنوات من أحداث «سيوف الآخرة»، دوي الرصاص، وانفجار الدم، وتفجر الكراهية، وبؤس الفتن اليومية، والجميع الذين قلوبهم شتى.\nاقرأها لتكون شاهدًا على الجريمة لو استدعاك المستقبل للإدلاء بشهادتك...\n*\nوصلت رواية «رحلة الدم» (الجزء الأول من ثلاثية القتلة الأوائل) إلى القائمة الطويلة لجائزة الشيخ زايد للكتاب - فرع الآداب عام 2017، ثم فازت بجائزة نجيب محفوظ للرواية عام 2018. ووصلت أيضًا رواية «حروب الرحماء» (الجزء الثاني من الثلاثية) إلى القائمة الطويلة لجائزة الشيخ زايد للكتاب - فرع الآداب عام 2019. وحققتا نجاحًا جماهيريًّا ونقديًّا كبيرًا، وبيعت منهما عشرات الآلاف من النسخ حتى الآن.",
